# Part 5: OOP, Properties, Inheritance, and Dunder Methods

from abc import ABC, abstractmethod

# Abstract Base Class
class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

# Class Inheritance and Encapsulation
class Circle(Shape):
    def __init__(self, radius):
        self._radius = radius  # Protected attribute

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value <= 0:
            raise ValueError("Radius must be positive")
        self._radius = value

    def area(self):
        return 3.14159 * self._radius ** 2

    # Dunder methods
    def __str__(self):
        return f"Circle(radius={self._radius})"

    def __add__(self, other):
        return Circle(self._radius + other._radius)

c1 = Circle(5)
c2 = Circle(3)
c3 = c1 + c2
print(f"{c3}, Combined Area: {c3.area():.2f}")

# Part 6: Generators, Closures, and Decorators

import functools

# Custom Decorator Factory
def repeat(num_times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(num_times):
                res = func(*args, **kwargs)
            return res
        return wrapper
    return decorator

@repeat(num_times=2)
def greet(name):
    print(f"Hello, {name}!")

greet("Bob")

# Generator function yielding values lazily
def countdown(n):
    while n > 0:
        yield n
        n -= 1

gen = countdown(3)
print(list(gen))  # [3, 2, 1]
